mapper.select:
SELECT cs.grade, cs.status, cs.create_time, c.id AS course_id, c.course_name, c.description, c.course_type, c.semester, c.location, c.teacher_id, t.real_name AS teacher_name, u.avatar AS teacher_avatar, c.cover_image_url, c.status AS course_status, c.is_public, c.create_time AS course_create_time, c.update_time AS course_update_time FROM mg_course_student cs LEFT JOIN mg_course c ON cs.course_id = c.id AND c.is_deleted = 0 LEFT JOIN mg_teacher t ON c.teacher_id = t.id LEFT JOIN sys_user u ON t.sys_user_id = u.id
cs.student_id = #{studentId}
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.status = #{status}
AND c.is_public = #{isPublic}
AND cs.create_time >= #{startTime}
AND cs.create_time <= #{endTime}
AND cs.create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}
ORDER BY cs.create_time DESC
